using namespace civ5;using namespace civ5::runtime;
namespace {
void check(bool v,const char *why){if(!v)throw std::runtime_error(why);}
template<class F>void rejects(F f,const char *why){try{f();}catch(const std::exception &){return;}throw std::runtime_error(why);}
void scalar(auto &fields,const char *name,std::int64_t value){typename std::remove_reference_t<decltype(fields)>::value_type f{};f.name=name;f.values={value};fields.push_back(f);}
saves::CityTailNode node(const char *name,std::int64_t value){saves::CityTailNode n{};n.name=name;n.encoding="i32";n.values={value};return n;}
void add_city(LiveSessionState &state,std::size_t owner,std::vector<CityYieldReligion> status){
 constexpr auto bnw=saves::GameStateLayout::expansion2_version1;saves::SavedCityObservation raw{};raw.core.layout=bnw;raw.core.version=6;raw.core.start_offset=1000+owner*10;raw.core.end_offset=raw.core.start_offset+5;scalar(raw.core.fields,"m_iID",0);scalar(raw.core.fields,"m_eOwner",owner);raw.tail.layout=bnw;raw.tail.context.bnw_city_version=6;saves::CityTailNode rel{};rel.name="religions";rel.encoding="block";rel.children.push_back(node("version",3));saves::CityTailNode list{};list.name="m_ReligionStatus";list.encoding="signed_records";list.wire_count=status.size();for(const auto &s:status){saves::CityTailNode r{};r.name="religion";r.encoding="block";r.children={node("version",2),node("m_eReligion",s.religion),node("m_iFollowers",s.followers),node("m_iPressure",s.pressure)};list.children.push_back(r);}rel.children.push_back(list);raw.tail.blocks.push_back(rel);state.world.all_players->players[owner].cities.cities.push_back(raw);CityYieldState live;live.owner=owner;live.id=0;live.source_core=std::pair{raw.core.start_offset,raw.core.end_offset};live.religions=std::move(status);state.cities.players.at(owner).cities[0]=std::move(live);
}
std::unique_ptr<content::RulesDatabase> fixture_database(){auto db=std::make_unique<content::RulesDatabase>();db->apply_sql("CREATE TABLE Beliefs(ID INTEGER,Type TEXT,PlayerHappiness INTEGER,RequiresPeace INTEGER,HappinessPerFollowingCity REAL,HappinessPerXPeacefulForeignFollowers INTEGER)");db->apply_sql("INSERT INTO Beliefs VALUES(0,'BELIEF_A',7,1,0.5,4),(1,'BELIEF_B',2,0,0.25,10)");return db;}
LiveSessionState fixture_world(){
 LiveSessionState state{.random={SimulationRandom(RandomAlgorithm::bnw,{}),SimulationRandom(RandomAlgorithm::bnw,{})}};constexpr auto bnw=saves::GameStateLayout::expansion2_version1;state.setup.profile=content::TechnologyProfile::bnw;state.setup.game_turn=19;state.cities.profile=content::TechnologyProfile::bnw;state.world.game_state.layout=bnw;state.world.payload_end_offset=20000;auto &r=state.world.religion_culture;r.layout=bnw;r.religions_version=4;r.start_offset=10;r.culture_offset=30;r.end_offset=50;
 state.world.pregame=saves::PregameObservation{};state.world.pregame->layout=bnw;state.world.all_players=saves::AllPlayersObservation{};state.world.all_players->layout=bnw;state.world.teams=saves::TeamsObservation{};state.world.teams->layout=bnw;
 for(std::size_t p=0;p<64;++p){ResearchPlayerState player;player.team=p;player.alive=p==0||p==1||p==63;state.setup.players[p]=player;state.cities.players[p]={};state.world.pregame->slots.integer_arrays["team_types"].push_back(p);saves::SavedPlayerObservation raw{};raw.index=p;raw.saved_player_id=p;raw.core.layout=bnw;scalar(raw.core.fields,"m_eID",p);scalar(raw.core.fields,"m_bAlive",player.alive);raw.cities.layout=bnw;state.world.all_players->players.push_back(raw);saves::TeamObservation team{};team.index=p;team.fields={{"id",static_cast<std::int64_t>(p)},{"alive_count",player.alive?1:0}};saves::PlotArrayObservation war{"at_war",1,std::vector<std::int64_t>(64)};team.arrays.push_back(war);state.world.teams->teams.push_back(team);}
 state.world.map_header.layout=bnw;state.world.map_header.grid={2,1};state.world.map_projection=saves::SavedMapProjection{};state.world.map_projection->grid={2,1};state.world.map_plots=saves::MapPlotsObservation{};state.world.map_plots->layout=bnw;for(std::size_t i=0;i<2;++i){saves::SavedMapCellProjection cell;cell.index=i;cell.x=i;cell.y=0;cell.owner=i;state.world.map_projection->cells.push_back(cell);saves::PlotObservation plot{};plot.index=i;plot.x=i;plot.y=0;plot.fields={{"owner",static_cast<std::int64_t>(i)}};state.world.map_plots->plots.push_back(plot);}
 for(std::int32_t id=1;id<=2;++id){saves::ReligionObservation rel{};rel.version=4;rel.religion=id;rel.founder=0;rel.holy_city_x=0;rel.holy_city_y=0;rel.beliefs.version=2;if(id==1)rel.beliefs.belief_hashes={content::saved_info_type_hash("BELIEF_B"),content::saved_info_type_hash("BELIEF_A"),content::saved_info_type_hash("BELIEF_A")};state.world.religion_culture.religions.push_back(rel);CityYieldReligionBeliefs cached;cached.religion=id;cached.founder=0;if(id==1)cached.beliefs={1,0,0};state.cities.religions.push_back(cached);}
 add_city(state,0,{{1,2,10},{2,2,1}});add_city(state,1,{{2,5,20},{1,13,0},{2,999,1}});add_city(state,63,{{1,200,10},{2,100,1}});add_city(state,2,{{2,1000,20}});return state;
}
// Explicit contract fixture. No stock listener/context claim.
class FixtureOwner:public BnwGameplayLuaEpochOwner{
 public:SavedContentProfile profile;SessionCheckpointIdentity identity;std::string script="local n=0;GameEvents.GetFounderBenefitsReligion.Add(function(p)assert(p==0);n=n+1;return n==1 and 1 or 2 end);GameEvents.FixtureCallCount.Add(function()return n end)";bool attest=true,missing=false;int publishes=0;std::function<void(LiveSessionState&)> on_map_call;
 FixtureOwner(const BnwReligionHappinessRules &rules){profile.can_activate=true;profile.all_requirements_located=true;profile.enabled_dlc={2,5};identity={std::string(64,'a'),rules.rules_sha256()};}
 BnwGameplayLuaForkResult fork_at(const LiveSessionState &state)override{if(missing)return {{},"stock Lua lifecycle missing"};auto e=std::make_unique<BnwTeamTechLuaEpoch>();e->world=std::make_unique<LiveSessionState>(state);e->source_world=&state;e->getter_world=e->world.get();e->identity=identity;e->selected_dlc=profile.enabled_dlc;e->all_selected_contexts_loaded=attest;e->all_listeners_registered=attest;e->all_external_writes_escrowed=attest;ScriptMapProvider map;map.grid_size=[]{return std::pair<std::int64_t,std::int64_t>{2,1};};map.random=[this,w=e->world.get()](std::int64_t,std::string_view){if(on_map_call)on_map_call(*w);return std::int64_t{0};};e->host=std::make_unique<LuaScriptHost>(ScriptBudget{8*1024*1024,1000000},ScriptSourceProvider{},ScriptModdingProvider{},ScriptGameplayProvider{},ScriptSaveDataProvider{},ScriptPregameProvider{},std::move(map));e->host->execute("fixture-only",script,"=not-stock-listeners");e->host->complete_loading();return {std::move(e),{}};}
 BnwGameplayLuaPublishResult publish(std::unique_ptr<BnwTeamTechLuaEpoch>,LiveSessionState&)override{++publishes;return {false,false,"fixture never publishes"};}
};
void fixture_checks(){
 auto db=fixture_database();auto rules=BnwReligionHappinessRules::load(*db);auto state=fixture_world();FixtureOwner owner(rules);const auto query=[&]{return quote_bnw_happiness_from_religion_terms(state,owner.profile,owner.identity,owner,rules,0);};
 const auto members=rules.terms(state.world.religion_culture.religions[0],true);check(members.player_happiness==9&&members.per_following_city==0.75f&&members.peaceful_foreign_divisor==4,"Belief native membership/slot-order/first-positive-divisor differs");auto foreign=BnwReligionFollowersReadModel::bind(state);check(foreign.at_peace(0)&&foreign.cities_following(1)==2&&foreign.peaceful_foreign_followers(0,2)==5,"Real status majority/first followers/source player loops differ");
 auto completed=query();check(completed.query.happiness_quoted&&completed.query.happiness==11&&completed.terms&&completed.terms->player_happiness==9&&completed.terms->following_cities==2&&completed.terms->following_happiness==1&&completed.terms->foreign_happiness==1&&completed.terms->foreign_founder_religion==2&&completed.terms->founder_callback_calls==2,"Founded terms did not consume second founder ID in same epoch");check(completed.query.epoch->host->accumulate_int("FixtureCallCount").value==2,"VM was reforked or callback omitted");
 state.world.teams->teams[0].arrays[0].values[63]=1;check(query().query.happiness==11,"Barbarian war incorrectly disables RequiresPeace");state.world.teams->teams[0].arrays[0].values[1]=1;state.world.teams->teams[1].arrays[0].values[0]=1;auto war=query();check(war.query.happiness==3&&!war.terms->at_peace&&war.terms->player_happiness==2&&war.terms->following_happiness==1&&war.terms->peaceful_foreign_followers==0,"Peace gating improperly changed following/divisor terms");state.world.teams->teams[0].arrays[0].values[1]=0;state.world.teams->teams[1].arrays[0].values[0]=0;
 auto unknown=state;unknown.cities.players[1].cities[0].religions[0].followers=6;rejects([&]{BnwReligionFollowersReadModel::bind(unknown);},"Stale follower cache was accepted");unknown=state;unknown.world.all_players->players[1].cities.cities[0].tail.blocks[0].children.pop_back();rejects([&]{BnwReligionFollowersReadModel::bind(unknown);},"Missing status collection became zero followers");unknown=state;unknown.world.teams->teams[1].fields[1].value=0;rejects([&]{BnwReligionFollowersReadModel::bind(unknown);},"Stale team alive count accepted");unknown=state;unknown.world.all_players->players[1].cities.cities[0].tail.blocks[0].children[1].children[0].children.erase(unknown.world.all_players->players[1].cities.cities[0].tail.blocks[0].children[1].children[0].children.begin());rejects([&]{BnwReligionFollowersReadModel::bind(unknown);},"Unknown city religion record version accepted");
 unknown=state;unknown.world.teams->teams[0].arrays[0].values[0]=1;rejects([&]{BnwReligionFollowersReadModel::bind(unknown);},"Unapplied native self-war repair was hidden");
 auto wrong=owner.identity;wrong.rules_sha256=std::string(64,'f');check(!quote_bnw_happiness_from_religion_terms(state,owner.profile,wrong,owner,rules,0).query.epoch,"Wrong selected rule owner accepted");owner.missing=true;check(!query().query.happiness_quoted,"Missing stock epoch bypassed");owner.missing=false;owner.attest=false;check(!query().query.happiness_quoted,"Empty unverified VM bypassed");owner.attest=true;
 owner.on_map_call=[](LiveSessionState &fork){++fork.setup.game_turn;};owner.script="local n=0;GameEvents.GetFounderBenefitsReligion.Add(function()n=n+1;if n==2 then Map.Rand(1,'second');error('nested fail')end;return 1 end)";auto failed=query();check(!failed.query.epoch&&!failed.query.happiness_quoted&&state.setup.game_turn==19&&owner.publishes==0,"Nested failure published partial callback/world effects");
 owner.script="local n=0;GameEvents.GetFounderBenefitsReligion.Add(function()n=n+1;return n==1 and 1 or -1 end)";auto none=query();check(none.query.happiness==10&&none.terms->foreign_founder_religion==-1&&none.terms->peaceful_foreign_followers==0,"Nested NO_RELIGION override was ignored");
 owner.script="GameEvents.GetFounderBenefitsReligion.Add(function()GameEvents.GetFounderBenefitsReligion.RemoveAll();return 1 end)";auto fallback=query();check(fallback.query.happiness==11&&fallback.terms->foreign_founder_religion==2,"Nested no-value accumulator did not execute native fallback");
 owner.script="local n=0;GameEvents.GetFounderBenefitsReligion.Add(function()n=n+1;assert(n==1);return nil end);GameEvents.FixtureCallCount.Add(function()return n end)";auto first_nil=query();check(first_nil.query.happiness_quoted&&first_nil.query.happiness==0&&first_nil.query.founder_religion==0&&!first_nil.terms&&first_nil.query.epoch->host->accumulate_int("FixtureCallCount").value==1,"First nil listener must override with native accumulated0, not native fallback or second hook");
 owner.script="local n=0;GameEvents.GetFounderBenefitsReligion.Add(function()n=n+1;if n==1 then return 1 end;return nil end)";auto second_nil=query();check(second_nil.query.happiness==10&&second_nil.terms->foreign_founder_religion==0&&second_nil.terms->founder_callback_calls==2&&second_nil.terms->peaceful_foreign_followers==0,"Second nil listener must override with native accumulated0, not absent registry fallback");
 auto zero_db=fixture_database();zero_db->apply_sql("UPDATE Beliefs SET HappinessPerXPeacefulForeignFollowers=0");auto zero_rules=BnwReligionHappinessRules::load(*zero_db);FixtureOwner zero_owner(zero_rules);zero_owner.script="local n=0;GameEvents.GetFounderBenefitsReligion.Add(function()n=n+1;assert(n==1);return 1 end)";auto one=quote_bnw_happiness_from_religion_terms(state,zero_owner.profile,zero_owner.identity,zero_owner,zero_rules,0);check(one.query.happiness==10&&one.terms->founder_callback_calls==1,"Zero divisor dispatched an extra callback");
  auto float_db=fixture_database();float_db->apply_sql("UPDATE Beliefs SET PlayerHappiness=0,HappinessPerFollowingCity=CASE WHEN ID=0 THEN 0.333333333 ELSE 0 END,HappinessPerXPeacefulForeignFollowers=0");auto float_rules=BnwReligionHappinessRules::load(*float_db);auto float_world=fixture_world();float_world.setup.players[2].alive=true;float_world.world.all_players->players[2].core.fields[1].values[0]=1;float_world.world.teams->teams[2].fields[1].value=1;float_world.cities.players[2].cities[0].religions[0].religion=1;float_world.world.all_players->players[2].cities.cities[0].tail.blocks[0].children[1].children[0].children[1].values[0]=1;FixtureOwner float_owner(float_rules);float_owner.script="GameEvents.GetFounderBenefitsReligion.Add(function()return 1 end)";auto float_quote=quote_bnw_happiness_from_religion_terms(float_world,float_owner.profile,float_owner.identity,float_owner,float_rules,0);check(float_quote.query.happiness==1&&float_quote.terms->following_cities==3&&float_quote.terms->following_happiness==1,"Native float32 rounding was replaced by double arithmetic");
 auto ids=state.world.religion_culture.religions[0];ids.beliefs.belief_hashes.push_back(0x01234567);check(rules.terms(ids,true).player_happiness==9,"Native unknown ReadHashed -1 became an active belief");ids.beliefs.version.reset();rejects([&]{rules.terms(ids,true);},"Unknown belief version became empty membership");
 check(owner.publishes==0&&state.setup.game_turn==19,"Terms quote published world or VM");
}
void selected_check(const char *save,const char *root){auto selected=ui::bootstrap_selected_bnw_preview(save,root,0);if(!selected.preview)throw std::runtime_error(selected.preview.blocker->reason);auto &host=*selected.preview.host;auto rules=BnwReligionHappinessRules::load(host.database());check(rules.rules_sha256()==host.identity().rules_sha256&&rules.belief_slots()>0,"Selected BNW rule owner identity/slots differ");const auto native=BnwReligionFollowersReadModel::bind(host.session().state());check(native.at_peace(0),"Selected Gandhi native peace query differs");FixtureOwner missing(rules);missing.profile=selected.profile;missing.identity=host.identity();missing.missing=true;auto blocked=quote_bnw_happiness_from_religion_terms(host.session().state(),selected.profile,host.identity(),missing,rules,0);check(!blocked.query.happiness_quoted&&!blocked.query.epoch&&!host.session().readiness().can_continue(),"Selected source rules/empty religions bypassed missing Lua");std::cout<<"Selected Gandhi rules+serialized followers model PASS; active Lua remains blocked; belief slots="<<rules.belief_slots()<<"\n";}
}
int main(int argc,char **argv){check(argc==1||argc==3,"Expected no args or selected save/game root");fixture_checks();if(argc==3)selected_check(argv[1],argv[2]);std::cout<<"PASS: BNW religious happiness terms, ordered nested Lua and atomic fixtures\n";}
